  // Basic correction (with the film's frame-to-frame flicker)
  c *= pow(2.0, uExposure * 1.5 + uBreath + uPush * 0.6);
  c.r += uTemp * 0.08;
  c.b -= uTemp * 0.08;
  c.g -= uTint * 0.06;
  c = clamp(c, 0.0, 1.0);
  c = clamp((c - 0.45) * (1.0 + uContrast * 0.6) + 0.45, 0.0, 1.0);
